import re

def _safe_compare(value, rhs, op):
    """Return op(value, rhs) but treat TypeError as non‑match.

    If the comparison raises TypeError (e.g., value is None or incomparable),
    return False so the document is skipped.
    """
    try:
        return op(value, rhs)
    except TypeError:
        return False
